    (2, 2807, 1, '1010102002', 1, 120, 0, null, null, '0', 'OLM', '2026-11-02 18:46:22', null, null),
    (2, 2807, 2, '1010201001', 1, 0, 120, null, null, '0', 'OLM', '2026-11-02 18:46:22', null, null),
    (2, 2808, 1, '1010102002', 1, 1650, 0, null, null, '0', 'OLM', '2026-11-02 18:47:39', null, null),
    (2, 2808, 2, '1010201001', 1, 0, 1650, null, null, '0', 'OLM', '2026-11-02 18:47:39', null, null),
    (2, 2809, 1, '1010102002', 1, 346, 0, null, null, '0', 'OLM', '2026-11-02 18:54:54', null, null),
    (2, 2809, 2, '1010201001', 1, 0, 346, null, null, '0', 'OLM', '2026-11-02 18:54:54', null, null)) as x(loc, documento, linea, codigo, version, debe, haber, debe_mi, haber_mi, centro, usr_ing, f_ing, usr_mod, f_mod) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    v_id := null;
    select id into v_id from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'DEPOSITO' and deposito_anterior = r.documento;
    if v_id is null then l_s := l_s + 1; continue; end if;
    v_cta := null;
    select k.id into v_cta from public.cuentas k join public.catalogos_cuentas g on g.id = k.catalogo_id
    where g.localidad_id = v_loc and k.codigo = r.codigo order by (g.version = r.version) desc, g.activo desc, g.version desc limit 1;
    if v_cta is null then l_c := l_c + 1; v_faltan := array_append(v_faltan, format('3-0%s %s', r.loc, r.codigo)); continue; end if;
    insert into public.movimiento_lineas (movimiento_id, linea, cuenta_id, debe, haber, debe_mi, haber_mi, cuenta_codigo_anterior, version_cuenta_anterior,
      centro_costo_anterior, usuario_ingresa_anterior, fecha_ingresa_anterior, usuario_modifica_anterior, fecha_modifica_anterior)
    values (v_id, r.linea, v_cta, r.debe, r.haber, r.debe_mi::numeric, r.haber_mi::numeric, r.codigo, r.version, r.centro::text, r.usr_ing::text, r.f_ing::timestamp, r.usr_mod::text, r.f_mod::timestamp)
    on conflict (movimiento_id, linea) do update set cuenta_id = excluded.cuenta_id, debe = excluded.debe, haber = excluded.haber, debe_mi = excluded.debe_mi,
      haber_mi = excluded.haber_mi, cuenta_codigo_anterior = excluded.cuenta_codigo_anterior, version_cuenta_anterior = excluded.version_cuenta_anterior,
      centro_costo_anterior = excluded.centro_costo_anterior, usuario_ingresa_anterior = excluded.usuario_ingresa_anterior, fecha_ingresa_anterior = excluded.fecha_ingresa_anterior,
      usuario_modifica_anterior = excluded.usuario_modifica_anterior, fecha_modifica_anterior = excluded.fecha_modifica_anterior
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then l_n := l_n + 1; else l_a := l_a + 1; end if;
  end loop;

  alter table public.movimientos_bancarios enable trigger movimientos_bancarios_preparar;
  alter table public.movimiento_lineas enable trigger movimiento_lineas_validar;

  raise notice '%', format('Depósitos: %s nuevos, %s actualizados, %s sin cuenta bancaria; %s recibos físicos. Detalle contable: %s líneas nuevas, %s actualizadas, %s sin depósito, %s sin cuenta.',
    c_n, c_a, c_s, d_n, l_n, l_a, l_s, l_c);
  if l_c > 0 then raise notice 'Cuentas que no existen en el catálogo de la localidad (líneas omitidas): %.', (select string_agg(distinct x, ', ') from unnest(v_faltan) x); end if;
end;
$migra$;

notify pgrst, 'reload schema';
